def main():
    prep_path=A/'EVOCATION_RANK5_SOURCE_PREPARATION.json'
    cat_path=R/'data/public/spell_playtests/catalog.json'
    idx_path=cat_path.with_name('authored_review_index.json')
    draft=A/'EVOCATION_RANK5_OPERATING_PROPOSALS.json'
    out=R/'data/director/spell_proposals/evocation_rank5.json'
    doc=R/'docs/spells/proposals/EVOCATION_RANK5.md'
    receipt=A/'EVOCATION_RANK5_OPERATING_PROPOSAL_CHECK.json'
    assert not any(p.exists() for p in [draft,out,doc,receipt]), 'One-use authoring: preserve earlier outputs'
    prep=read(prep_path);cat=read(cat_path);idx=read(idx_path)
    selected={s['spellId']:s for s in prep['selectedSpells']}
    catalog={s['id']:s for s in cat['spells']};entries={s['id']:s for s in idx['entries']}
    checks=[]
    def check(label,ok):
        checks.append({'name':label,'pass':bool(ok)})
        assert ok,label
    check('Eight distinct complete EV5 mechanical proposals',len(P)==len({p['spellId'] for p in P})==8 and {p['spellId'] for p in P}==set(selected))
    check('No post-push spell authored',all(x['scope']=='pre-push mechanical source question' for x in selected.values()))
    check('848 ordinary spells and unchanged reviewed totals',len(catalog)==848 and idx['authoredCounts']=={'reviewed':412,'pending':436})
    inputs={prep_path,cat_path,idx_path,Path(__file__).resolve()}
    records=[]
    for p in P:
        s=selected[p['spellId']];original=catalog[p['spellId']]
        digest=sha256(json.dumps(original,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode('utf-8')).hexdigest()
        check(p['spellId']+' complete source/access preserved',original==s['fullSourceAndCurrentAccessRecord'] and digest==s['recordSha256'])
        check(p['spellId']+' remains pending',entries[p['spellId']]['authoredStatus']=='pending-authored-procedure' and original['operational'] is None)
        check(p['spellId']+' actual rank5/base10 rows retained',all(x['rank']==5 and x['baseRpCost']==10 for x in original['classAccess'].values()))
        check(p['spellId']+' two complete authored examples',len(p['workedCases'])==2 and all(len(x)>150 for x in p['workedCases']))
        records.append({**p,'questionId':s['questionId'],'originalQuestion':s['individualQuestion'],'fullSourceAndCurrentAccessRecord':original,'sourceRecordSha256':digest,'status':'unadopted-unsent-operating-proposal','examplesAreRuntimeTests':False})
    records.sort(key=lambda x:x['questionId'])
    counterparts=[]
    for original in prep['completeCounterparts']:
        sid=original['id'];e=entries[sid];path=cat_path.parent/e['procedureFile'];d=read(path);inputs.add(path)
        for k in e['wholeCardPointer'].strip('/').split('/'):d=d[int(k)] if isinstance(d,list) else d[k]
        check(sid+' complete current counterpart retrieved',d.get('id',d.get('spellId'))==sid)
        check(sid+' actual reviewed/pending distinction', (e['authoredStatus']=='reviewed-authored-operational-playtest' and isinstance(d.get('operational',d.get('operationalCandidate')),dict)) or (e['authoredStatus']=='pending-authored-procedure' and d.get('operational') is None))
        counterparts.append({'id':sid,'preparedCompleteRecord':original,'currentSourceCatalogRecord':catalog[sid],'currentAuthoredIndexEntry':e,'completeCurrentAuthoredRecord':d})
    check('All17 current counterparts',len(counterparts)==17)
    earlier_path=R/'data/director/spell_proposals/evocation_rank4.json';earlier=read(earlier_path);inputs.add(earlier_path)
    wanted={x['id'] for x in counterparts if x['currentAuthoredIndexEntry']['authoredStatus']=='pending-authored-procedure'}
    prior=[x for x in earlier['records'] if x['spellId'] in wanted]
    check('All seven pending counterparts retain their full earlier unadopted proposals',len(prior)==len(wanted)==7 and {x['spellId'] for x in prior}==wanted and all(x['status']=='unadopted-unsent-operating-proposal' for x in prior))
    guides={}
    for x in prep['currentGoverningExcerpts']:
        p=G/x['file'];inputs.add(p)
        guides.setdefault(x['file'],{'currentFile':info(p),'fullCurrentText':p.read_text('utf-8'),'preparedExcerpts':[]})['preparedExcerpts'].append(x)
    for name in ['CLASS_PLAYTEST_RULES.md','CUSTOM_CONDITION_BINDINGS.md','CONDITION_RECOVERY_PLAYTEST.md','MAXIMUM_HP_PLAYTEST.md']:
        p=R/'docs/mechanics'/name;inputs.add(p)
