    check('Actual Wizard9 maximum32',core['caster_pools']['Wizard'][8]==32)
    low_path=cat_path.with_name('candidate_low_rank_136.json');inputs.add(low_path);lower=read(low_path)
    current_status=R/'docs/mechanics/expedition/EXPEDITION_REVIEW_STATUS.json';inputs.add(current_status);review_status=read(current_status)
    check('EX58 exact authored gate carried forward',review_status['exactCandidateAuthoredApproval'] is True and review_status['selectionEnabled'] is False and review_status['runtimeImplemented'] is False)
    current_changes=review_status['currentArtifactBindings']
    package=read(A/'EX58_EXACT_CANDIDATE_PACKAGE.json');preserved=0;amended=0
    for rel,expected in package['manifest'].items():
        p=G/rel
        if p.is_file():
            actual_expected=current_changes.get(rel,expected)
            check('Submitted source or exact reviewed EX58 descendant: '+rel,info(p)==actual_expected)
